  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'Letras aparecem junto de outros sinais', 'Cartazes e telas misturam sinais diferentes. Letras formam palavras; algarismos registram números; pontuação organiza a escrita; imagens e ícones comunicam visualmente. Cor e tamanho não mudam a categoria.', '## Observe cada marca
Uma palavra é formada por letras do alfabeto. Em “SOL”, S, O e L são letras. Em “SOL 3!”, o 3 é um algarismo e ! é pontuação. Um desenho de estrela pode ilustrar ou indicar algo, mas não é uma letra. Esses sinais podem aparecer juntos no mesmo cartaz.

## Forma e função não são a mesma coisa
Uma letra pode aparecer grande, pequena, colorida, maiúscula ou minúscula e continuar sendo letra. Um algarismo também pode ser colorido sem deixar de registrar um número. Se dois sinais parecem parecidos, observe como são usados: uma marca dentro de uma palavra pode ser letra; numa escrita numérica, pode ser algarismo.

## Ícones também comunicam
Uma seta, um alto-falante desenhado ou uma figura podem indicar uma ação. Eles comunicam visualmente, mas não pertencem ao alfabeto. O nome escrito de uma figura é outra coisa: no desenho de uma lua e na palavra “LUA”, a ilustração não é letra, enquanto L, U e A são.

## Exemplo resolvido
No convite “FESTA 5? VEM!”, as letras formam FESTA e VEM; 5 é algarismo; ? e ! são pontuação. Uma figura de balão pode decorar o convite. É possível apontar uma letra dentro de FESTA mesmo que um adulto leia a frase: a atividade não exige que a criança decodifique tudo sozinha.

## Roteiro
1. Separe uma marca por vez. 2. Veja se pertence a uma palavra, a uma escrita numérica, à pontuação ou a uma imagem/ícone. 3. Não use cor ou tamanho como regra. 4. Se a leitura for difícil, peça que alguém leia o contexto e continue classificando os sinais.',
    'Em “MIA, 3 anos!”, M, I e A são letras da palavra MIA; 3 é algarismo; a vírgula e o ponto de exclamação são pontuação. A foto ao lado ilustra a pessoa. A criança pode localizar uma letra sem ler a legenda inteira.', array['Aponte cada sinal, sem classificar a linha inteira de uma vez.', 'Procure letras dentro de uma palavra curta.', 'Compare algarismo, pontuação e ícone com exemplos no mesmo material.', 'Maiúscula e minúscula são formas diferentes de letras.', 'Quando necessário, aceite leitura mediada, apontar ou parear cartões.']::text[], 18, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-portuguese-letters-signs","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Observar marcas em livros, placas, embalagens e telas.","Perceber que sinais diferentes podem comunicar coisas diferentes."],"key_concepts":["Letras do alfabeto formam palavras.","Algarismos registram números.","Pontuação organiza ou marca relações na escrita.","Ícones e ilustrações comunicam por imagens, mas não são letras.","Cor, tamanho e proximidade não determinam a categoria do sinal."],"progression":[{"stage":"FOUNDATION","focus":"Reconhecer letra, algarismo e pontuação em exemplos curtos.","questionIds":["v5-pt-signs-probe-01","v5-pt-signs-probe-02","v5-pt-signs-probe-03","v5-pt-signs-practice-01","v5-pt-signs-practice-02","v5-pt-signs-practice-03"]},{"stage":"APPLICATION","focus":"Classificar sinais misturados em etiquetas, telas e materiais familiares.","questionIds":["v5-pt-signs-practice-04","v5-pt-signs-practice-05","v5-pt-signs-practice-06","v5-pt-signs-practice-07","v5-pt-signs-practice-08"]},{"stage":"INTERMEDIATE","focus":"Distinguir função de decoração e usar o contexto para sinais parecidos.","questionIds":["v5-pt-signs-practice-09","v5-pt-signs-practice-10","v5-pt-signs-practice-11","v5-pt-signs-transfer-01","v5-pt-signs-transfer-02"]},{"stage":"ADVANCED_TRANSFER","focus":"Explicar classificações em suportes novos e com leitura mediada.","questionIds":["v5-pt-signs-transfer-03","v5-pt-signs-transfer-04","v5-pt-signs-transfer-05","v5-pt-signs-transfer-06","v5-pt-signs-transfer-07","v5-pt-signs-lock-01","v5-pt-signs-lock-02","v5-pt-signs-lock-03","v5-pt-signs-lock-04","v5-pt-signs-lock-05"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Retomar categorias em materiais cotidianos e casos de aparência semelhante.","questionIds":["v5-pt-signs-review-01","v5-pt-signs-review-02","v5-pt-signs-review-03","v5-pt-signs-review-04","v5-pt-signs-review-05","v5-pt-signs-review-06","v5-pt-signs-review-07","v5-pt-signs-review-08","v5-pt-signs-review-09"]}],"micro_explanations":[{"trigger":"LETTER_AS_NUMBER","text":"Veja se a marca pertence ao alfabeto e aparece formando uma palavra. Algarismos registram números."},{"trigger":"PUNCTUATION_AS_LETTER","text":"Pontuação pode aparecer perto das letras, mas tem outra função: observe o sinal que organiza ou encerra a frase."},{"trigger":"COLOR_AS_CATEGORY","text":"A cor pode mudar sem mudar o tipo do sinal. Um 5 verde continua algarismo; uma letra vermelha continua letra."},{"trigger":"ICON_AS_LETTER","text":"Diferencie a imagem do nome escrito: desenho de lua não é a mesma coisa que as letras L, U, A."}],"remediations":[{"misconception":"LETTER_AS_NUMBER","prompt":"Use cartões separados com uma letra e um algarismo. Aponte cada marca e diga se ela pode aparecer formando uma palavra ou registrando um número."},{"misconception":"PUNCTUATION_AS_LETTER","prompt":"Leia uma frase curta em voz alta e compare as letras dentro da palavra com o sinal no começo ou final. Aponte a função, não apenas a posição."},{"misconception":"COLOR_AS_CATEGORY","prompt":"Mostre a mesma letra em duas cores e um algarismo colorido. Classifique pelo tipo e pelo uso, cobrindo as cores para comparar."},{"misconception":"ICON_AS_LETTER","prompt":"Coloque lado a lado um desenho e a palavra que o nomeia. A criança pode apontar letras na palavra sem precisar ler outras partes do texto."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Base Nacional Comum Curricular: Língua Portuguesa do Ensino Fundamental","publisher":"Ministério da Educação","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","accessedOn":"2026-10-13","supports":["A fonte apresenta EF01LP04: distinguir letras do alfabeto de outros sinais gráficos."],"use":"Referência de escopo, não aprovação do mapeamento desta habilidade interna. A revisão pedagógica humana continua pendente."}],"copyright_note":"Enunciados, alternativas, explicações e atividade foram escritos para este pacote. O dossiê oficial informa o escopo de referência; não há cópia de questão nem reivindicação de mapeamento aprovado.","authentic_activities":[{"id":"portuguese-signs-classroom-sort","title":"Caça aos sinais no cartaz","objective":"Localizar letras em palavras e distinguir algarismos, pontuação e ícones em materiais familiares.","context":"A turma observa um cartaz fictício preparado pelo professor, com palavras curtas, um número, pontuação e ilustrações simples.","materials":["Cartaz impresso em tamanho legível","Cartões com letras, algarismos, pontuação e imagens","Lápis de cor ou marcadores opcionais"],"instructions":"O adulto lê o cartaz se necessário. A criança aponta ou pareia sinais em quatro grupos: letras dentro de palavras, algarismos, pontuação e imagens/ícones. Depois escolhe uma marca e explica como a identificou. Varie cor e tamanho dos cartões para verificar se a criança usa a categoria e a função, não a decoração. Não cronometre nem exija leitura independente do texto.","evidence":"A criança localiza letras em uma palavra curta e classifica pelo menos um exemplo de algarismo, pontuação e imagem, com o tipo de apoio registrado.","safety":"Use material sem peças pequenas para crianças que possam levá-las à boca; ofereça cartões grandes e de alto contraste. Não exponha nomes ou fotos reais de estudantes.","ageRange":"1º ano do Ensino Fundamental; selecionar letras familiares e permitir que o adulto leia o contexto.","mediation":"O adulto pode ler as palavras e registrar se a criança aponta, nomeia, pareia ou explica. Não interpretar dificuldade de decodificação como falha em distinguir sinais.","privacyGuard":"Use conteúdo fictício e não registre imagens, nomes completos ou produções identificáveis das crianças.","rubric":[{"criterion":"Localização de letras","emerging":"Ainda não localiza letras mesmo com apoio visual.","developing":"Aponta uma letra em palavra curta após mediação.","proficient":"Localiza letras em palavras curtas sem depender da leitura integral."},{"criterion":"Distinção entre categorias","emerging":"Agrupa marcas sem diferenciar letras, algarismos, pontuação e imagem.","developing":"Distingue algumas categorias com cartões-modelo.","proficient":"Classifica exemplos das quatro categorias e justifica usando tipo ou função."},{"criterion":"Uso do contexto","emerging":"Baseia a classificação somente em cor, tamanho ou posição.","developing":"Usa o contexto após uma pergunta orientadora.","proficient":"Explica que decoração ou proximidade não altera a categoria do sinal."}]}],"objective":"Localizar letras em palavras e diferenciá-las de algarismos, pontuação e ícones em materiais cotidianos, sem exigir leitura autônoma de textos longos.","common_mistake":"Chamar qualquer marca impressa de letra; usar cor/tamanho para classificar; confundir imagem com o nome escrito da imagem; exigir leitura autônoma para avaliar a categoria de um sinal.","estimated_minutes":18}'::jsonb
