  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-pt-signs-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"CLASSIFY","contextFamily":"INVITATION_CARD","statement":"No convite “BIA 6!”, qual sinal é um algarismo?","options":["6","B","!","A"],"correctAnswer":"6","explanation":"O 6 registra um número; B e A são letras, e ! é pontuação.","hint":"Procure a marca que pode indicar uma quantidade ou idade.","errorFocus":"Confundir letra e algarismo","misconceptions":{"B":["LETTER_AS_NUMBER"],"!":["PUNCTUATION_AS_NUMBER"],"A":["LETTER_AS_NUMBER"]},"position":1},{"id":"v5-pt-signs-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"RECOGNIZE","contextFamily":"NAME_LABEL","statement":"Uma etiqueta mostra a palavra “LUA”. Qual alternativa é uma letra que aparece nela?","options":["3","U","?","desenho de lua"],"correctAnswer":"U","explanation":"U faz parte da escrita alfabética da palavra LUA.","hint":"Aponte uma marca que forma a palavra.","errorFocus":"Tratar todo sinal visual como letra","misconceptions":{"3":["DIGIT_AS_LETTER"],"?":["PUNCTUATION_AS_LETTER"],"desenho de lua":["ICON_AS_LETTER"]},"position":2},{"id":"v5-pt-signs-probe-03","purpose":"PROBE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"DIGITAL_MESSAGE","statement":"Em uma tela aparece “OI :)”. O que é “:)” nesse contexto?","options":["Uma palavra formada pelas letras O e I.","Um algarismo que indica quantidade.","Um sinal visual que representa uma expressão, não uma letra do alfabeto.","Uma letra minúscula diferente de O."],"correctAnswer":"Um sinal visual que representa uma expressão, não uma letra do alfabeto.","explanation":"O sinal gráfico comunica uma expressão por combinação visual; não é letra do alfabeto.","hint":"Compare o sinal com as letras O e I.","errorFocus":"Confundir ícone com letra","misconceptions":{"Uma palavra formada pelas letras O e I.":["WORD_AS_ICON"],"Um algarismo que indica quantidade.":["ICON_AS_NUMBER"],"Uma letra minúscula diferente de O.":["CASE_AS_CATEGORY"]},"position":3},{"id":"v5-pt-signs-practice-01","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"CLASSIFY","contextFamily":"BOOK_TITLE","statement":"Na capa “SOL”, qual marca é uma letra?","options":["5","?","desenho de estrela","S"],"correctAnswer":"S","explanation":"S é uma das letras que formam SOL.","hint":"Procure uma marca que faça parte da palavra.","errorFocus":"Confundir categorias de sinais","misconceptions":{"5":["DIGIT_AS_LETTER"],"?":["PUNCTUATION_AS_LETTER"],"desenho de estrela":["IMAGE_AS_LETTER"]},"position":1},{"id":"v5-pt-signs-practice-02","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"CLASSIFY","contextFamily":"PRICE_TAG","statement":"Uma etiqueta mostra “R$ 4”. Qual sinal é um algarismo?","options":["4","R","?","desenho de moeda"],"correctAnswer":"4","explanation":"4 é o algarismo que registra um número; R é letra e ? é pontuação.","hint":"Qual marca pode indicar uma quantidade numérica?","errorFocus":"Confundir símbolo monetário e algarismo","misconceptions":{"R":["LETTER_AS_NUMBER"],"?":["PUNCTUATION_AS_NUMBER"],"desenho de moeda":["ICON_AS_NUMBER"]},"position":2},{"id":"v5-pt-signs-practice-03","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"QUESTION_CARD","statement":"No cartão “VEM?”, qual sinal marca a pontuação?","options":["V","?","E","M"],"correctAnswer":"?","explanation":"O ponto de interrogação é pontuação; V, E e M são letras.","hint":"Observe a marca que aparece depois da palavra.","errorFocus":"Tratar pontuação como letra","misconceptions":{"V":["LETTER_AS_PUNCTUATION"],"E":["LETTER_AS_PUNCTUATION"],"M":["LETTER_AS_PUNCTUATION"]},"position":3},{"id":"v5-pt-signs-practice-04","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"UPPER_LOWER_CASE","statement":"A letra A aparece em “ANA” e em “Ana”. O que mudou?","options":["A primeira letra virou algarismo.","As letras minúsculas são pontuação.","A forma de algumas letras; elas continuam sendo letras.","A palavra deixou de ter letras."],"correctAnswer":"A forma de algumas letras; elas continuam sendo letras.","explanation":"Maiúscula e minúscula são formas de letras do alfabeto.","hint":"Compare a função das marcas, não apenas o tamanho.","errorFocus":"Tratar maiúsculas e minúsculas como categorias diferentes","misconceptions":{"A primeira letra virou algarismo.":["CASE_AS_DIGIT"],"As letras minúsculas são pontuação.":["LOWERCASE_AS_PUNCTUATION"],"A palavra deixou de ter letras.":["LETTER_AS_NONLETTER"]},"position":4},{"id":"v5-pt-signs-practice-05","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"CLASSIFY","contextFamily":"GAME_SCORE","statement":"Um placar mostra “TIME A: 2”. Qual item é pontuação?","options":["A","2","T",":"],"correctAnswer":":","explanation":"Os dois-pontos separam informações; A e T são letras e 2 é algarismo.","hint":"Procure um sinal que organiza a escrita, sem ser letra ou número.","errorFocus":"Confundir pontuação com letra ou número","misconceptions":{"2":["DIGIT_AS_PUNCTUATION"],"A":["LETTER_AS_PUNCTUATION"],"T":["LETTER_AS_PUNCTUATION"]},"position":5},{"id":"v5-pt-signs-practice-06","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"RECOGNIZE","contextFamily":"ARROW_BUTTON","statement":"Uma tela tem a palavra “VOLTAR” e, ao lado, uma seta desenhada. Qual item é um ícone?","options":["A seta desenhada.","A letra V.","A letra A.","A palavra VOLTAR inteira."],"correctAnswer":"A seta desenhada.","explanation":"A seta representa visualmente uma ação; V e A são letras da palavra.","hint":"Procure a imagem que indica uma ação.","errorFocus":"Confundir ícone e letra","misconceptions":{"A letra V.":["LETTER_AS_ICON"],"A letra A.":["LETTER_AS_ICON"],"A palavra VOLTAR inteira.":["WORD_AS_ICON"]},"position":6},{"id":"v5-pt-signs-practice-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"CLASSIFY","contextFamily":"BUS_STOP_SIGN","statement":"Uma placa mostra “RUA 8”. Qual afirmação classifica corretamente os sinais?","options":["R e 8 são letras porque aparecem juntos.","R e U são letras; 8 é algarismo.","U é pontuação e 8 é ícone.","Todos os sinais são algarismos."],"correctAnswer":"R e U são letras; 8 é algarismo.","explanation":"A proximidade não muda a natureza de cada marca: letras formam RUA e 8 registra um número.","hint":"Separe a palavra da marca numérica.","errorFocus":"Classificar todos os sinais pela vizinhança","misconceptions":{"R e 8 são letras porque aparecem juntos.":["NEIGHBOR_AS_SAME_TYPE"],"U é pontuação e 8 é ícone.":["LETTER_AS_PUNCTUATION"],"Todos os sinais são algarismos.":["ALL_AS_DIGITS"]},"position":7},{"id":"v5-pt-signs-practice-08","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"COLORED_POSTER","statement":"Em um cartaz, o O de “BOLA” está vermelho e o A está azul. Qual conclusão é adequada?","options":["O vermelho virou algarismo.","O azul virou ícone.","As cores mudam, mas O e A continuam sendo letras.","A letra colorida deixa de fazer parte da palavra."],"correctAnswer":"As cores mudam, mas O e A continuam sendo letras.","explanation":"Cor é decoração e não altera a categoria da letra.","hint":"Pense no papel do sinal dentro da palavra.","errorFocus":"Usar cor como critério de classificação","misconceptions":{"O vermelho virou algarismo.":["COLOR_AS_DIGIT"],"O azul virou ícone.":["COLOR_AS_ICON"],"A letra colorida deixa de fazer parte da palavra.":["COLOR_REMOVES_LETTER"]},"position":8},{"id":"v5-pt-signs-practice-09","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"CLASSIFY","contextFamily":"CALENDAR_DATE","statement":"No calendário está escrito “DIA 12.”. Qual item é pontuação?","options":["1","2","D","."],"correctAnswer":".","explanation":"O ponto final é pontuação; 1 e 2 são algarismos e D é letra.","hint":"Veja o sinal que encerra a frase.","errorFocus":"Confundir ponto final com algarismo","misconceptions":{"1":["DIGIT_AS_PUNCTUATION"],"2":["DIGIT_AS_PUNCTUATION"],"D":["LETTER_AS_PUNCTUATION"]},"position":9},{"id":"v5-pt-signs-practice-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"LOCATE","contextFamily":"WORD_BUILDING","statement":"Em “PATO”, qual alternativa aponta uma letra que está dentro da palavra?","options":["T","7","!","desenho de pato"],"correctAnswer":"T","explanation":"T é uma letra que integra a escrita de PATO; não é preciso ler outras frases para classificá-la.","hint":"Procure uma das marcas que compõem a palavra.","errorFocus":"Não localizar letra dentro de palavra","misconceptions":{"7":["DIGIT_AS_LETTER"],"!":["PUNCTUATION_AS_LETTER"],"desenho de pato":["IMAGE_AS_LETTER"]},"position":10},{"id":"v5-pt-signs-practice-11","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"SIMILAR_SHAPES","statement":"Em uma atividade, a criança confunde o algarismo 1 com a letra I porque parecem parecidos na fonte. O que ajuda a classificá-los?","options":["Dizer que sinais parecidos sempre têm a mesma função.","Observar como cada sinal é usado no contexto e comparar com a palavra ou número em que aparece.","Classificar pela cor, sem olhar onde aparece.","Afirmar que I nunca pode ser uma letra."],"correctAnswer":"Observar como cada sinal é usado no contexto e comparar com a palavra ou número em que aparece.","explanation":"A forma pode se parecer; a função e o contexto ajudam a distinguir as categorias.","hint":"Olhe para os sinais ao redor e para o que está sendo escrito.","errorFocus":"Usar semelhança visual como única regra","misconceptions":{"Dizer que sinais parecidos sempre têm a mesma função.":["SAME_SHAPE_SAME_TYPE"],"Classificar pela cor, sem olhar onde aparece.":["COLOR_ONLY"],"Afirmar que I nunca pode ser uma letra.":["LETTER_NEVER"]},"position":11},{"id":"v5-pt-signs-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"CLASSIFY","contextFamily":"PACKAGING_LABEL","statement":"Uma embalagem tem a palavra “ARROZ”, o número “1” e o desenho de uma tigela. Qual descrição é correta?","options":["ARROZ é pontuação; 1 é letra; a tigela é algarismo.","Tudo é letra porque está impresso na embalagem.","ARROZ é formado por letras; 1 é algarismo; a tigela é ilustração ou ícone.","O número 1 é ícone e a palavra é desenho."],"correctAnswer":"ARROZ é formado por letras; 1 é algarismo; a tigela é ilustração ou ícone.","explanation":"O suporte reúne sinais de tipos diferentes; estar impresso junto não os torna iguais.","hint":"Classifique cada parte separadamente.","errorFocus":"Classificar pelo suporte em vez da função","misconceptions":{"ARROZ é pontuação; 1 é letra; a tigela é algarismo.":["WORD_AS_PUNCTUATION"],"Tudo é letra porque está impresso na embalagem.":["ALL_AS_LETTERS"],"O número 1 é ícone e a palavra é desenho.":["NUMBER_AS_ICON"]},"position":1},{"id":"v5-pt-signs-transfer-02","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"PHOTO_CAPTION","statement":"Uma foto tem a legenda “MIA, 3 anos!”. Qual alternativa separa corretamente as marcas?","options":["3 é letra e M é algarismo.","A vírgula é ícone e a foto é pontuação.","Tudo que está na legenda é letra.","M, I e A são letras; 3 é algarismo; vírgula e ! são pontuação."],"correctAnswer":"M, I e A são letras; 3 é algarismo; vírgula e ! são pontuação.","explanation":"A legenda combina letras, número e pontuação, cada qual com uma função diferente.","hint":"Aponte um exemplo de cada tipo.","errorFocus":"Misturar categorias numa frase","misconceptions":{"3 é letra e M é algarismo.":["DIGIT_AS_LETTER"],"A vírgula é ícone e a foto é pontuação.":["PUNCTUATION_AS_ICON"],"Tudo que está na legenda é letra.":["ALL_AS_LETTERS"]},"position":2},{"id":"v5-pt-signs-transfer-03","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"RECOGNIZE","contextFamily":"AUDIO_BUTTON","statement":"Em um aplicativo, “OUVIR” está escrito ao lado de um desenho de alto-falante. Qual afirmação é correta?","options":["O desenho indica uma ação; O, U, V, I e R são letras da palavra.","O desenho é uma letra por ter formato conhecido.","A palavra OUVIR é um algarismo.","As letras deixam de ser letras quando ficam perto de uma figura."],"correctAnswer":"O desenho indica uma ação; O, U, V, I e R são letras da palavra.","explanation":"Ícone e palavra podem comunicar juntos sem pertencer à mesma categoria gráfica.","hint":"Separe o desenho das marcas escritas.","errorFocus":"Confundir proximidade entre ícone e palavra","misconceptions":{"O desenho é uma letra por ter formato conhecido.":["ICON_AS_LETTER"],"A palavra OUVIR é um algarismo.":["WORD_AS_NUMBER"],"As letras deixam de ser letras quando ficam perto de uma figura.":["NEIGHBOR_AS_SAME_TYPE"]},"position":3},{"id":"v5-pt-signs-transfer-04","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"CLASSROOM_SORT","statement":"Uma turma separa cartões apenas pela cor: todos os cartões azuis vão para “letras”. Por que essa regra falha?","options":["Porque letras só podem ser pretas.","A cor pode aparecer em letras, algarismos e outros sinais; é preciso observar o tipo e a função.","Porque cartões coloridos não têm sinais gráficos.","A regra está certa: azul sempre significa letra."],"correctAnswer":"A cor pode aparecer em letras, algarismos e outros sinais; é preciso observar o tipo e a função.","explanation":"Uma característica visual decorativa não determina se o sinal é letra, número ou pontuação.","hint":"Imagine um 4 azul e uma letra vermelha.","errorFocus":"Classificar pelo atributo decorativo","misconceptions":{"Porque letras só podem ser pretas.":["BLACK_ONLY"],"Porque cartões coloridos não têm sinais gráficos.":["COLOR_ERASES_SIGN"],"A regra está certa: azul sempre significa letra.":["COLOR_DEFINES_TYPE"]},"position":4},{"id":"v5-pt-signs-transfer-05","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"LOCATE","contextFamily":"STORY_PAGE","statement":"Uma página mostra “O GATO!” e a ilustração de um gato. Uma criança precisa apontar uma letra sem ler a história. O que ela pode apontar?","options":["Somente a ilustração do gato.","O ponto de exclamação, porque aparece perto das letras.","Qualquer uma das letras O, G, A ou T na escrita “O GATO!”.","A palavra inteira como se fosse uma única letra."],"correctAnswer":"Qualquer uma das letras O, G, A ou T na escrita “O GATO!”.","explanation":"O objetivo é localizar uma letra na escrita; não exige leitura autônoma do texto.","hint":"Escolha uma marca dentro das palavras impressas.","errorFocus":"Confundir ilustração, pontuação e letra","misconceptions":{"Somente a ilustração do gato.":["IMAGE_AS_LETTER"],"O ponto de exclamação, porque aparece perto das letras.":["PUNCTUATION_AS_LETTER"],"A palavra inteira como se fosse uma única letra.":["WORD_AS_SINGLE_LETTER"]},"position":5},{"id":"v5-pt-signs-transfer-06","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"TICKET_PRINT","statement":"Um bilhete tem “PORTA B” e “12”. Qual informação permite saber que B é letra e 12 é um número?","options":["B é número porque vem depois da palavra PORTA.","12 são letras porque aparecem perto de B.","A posição no papel transforma B em pontuação.","B faz parte de uma palavra ou identificação alfabética; 12 é escrito com algarismos."],"correctAnswer":"B faz parte de uma palavra ou identificação alfabética; 12 é escrito com algarismos.","explanation":"A classificação considera o tipo de sinal e seu uso, não apenas a posição ao lado de outro.","hint":"Observe quais marcas formam a palavra e quais registram número.","errorFocus":"Usar posição física como categoria","misconceptions":{"B é número porque vem depois da palavra PORTA.":["LETTER_AS_NUMBER"],"12 são letras porque aparecem perto de B.":["NUMBER_AS_LETTERS"],"A posição no papel transforma B em pontuação.":["POSITION_AS_PUNCTUATION"]},"position":6},{"id":"v5-pt-signs-transfer-07","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EXPLAIN","contextFamily":"LABEL_FOR_FAMILY","statement":"Você quer explicar a uma família como encontrar uma letra num cartaz que também tem números e desenhos. Qual orientação é mais útil?","options":["Procure uma marca do alfabeto dentro de uma palavra; número, pontuação e desenho são outros tipos de sinais.","Escolha o sinal mais colorido, pois ele sempre é uma letra.","Leia todo o cartaz sozinho antes de apontar uma letra.","Considere qualquer desenho como parte do alfabeto."],"correctAnswer":"Procure uma marca do alfabeto dentro de uma palavra; número, pontuação e desenho são outros tipos de sinais.","explanation":"A orientação aponta para a categoria sem exigir leitura independente de todo o cartaz.","hint":"Explique o que observar, não a velocidade de leitura.","errorFocus":"Exigir leitura longa para classificar sinal","misconceptions":{"Escolha o sinal mais colorido, pois ele sempre é uma letra.":["COLOR_AS_LETTER"],"Leia todo o cartaz sozinho antes de apontar uma letra.":["AUTONOMOUS_LONG_READ"],"Considere qualquer desenho como parte do alfabeto.":["IMAGE_AS_ALPHABET"]},"position":7},{"id":"v5-pt-signs-lock-01","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"CLASSIFY","contextFamily":"MENU_BOARD","statement":"No quadro “SOPA: R$ 8,00”, qual alternativa identifica algarismos?","options":["S e A.","8 e 0.",": e $.","O e P."],"correctAnswer":"8 e 0.","explanation":"8 e 0 são algarismos que registram o valor; letras e pontuação têm outras funções.","hint":"Procure as marcas que compõem a quantia numérica.","errorFocus":"Confundir letras e sinais de pontuação com algarismos","misconceptions":{"S e A.":["LETTER_AS_DIGIT"],": e $.":["PUNCT_AS_DIGIT"],"O e P.":["LETTER_AS_DIGIT"]},"position":1},{"id":"v5-pt-signs-lock-02","purpose":"LOCK_IN","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"LOWERCASE_SIGN","statement":"Em “sol!” e “SOL!”, o que continua igual?","options":["! vira letra quando a palavra está em mi