”","“A palavra VAI tem três letras?”"],"correctAnswer":"“Esse sinal faz parte do alfabeto ou indica pontuação na frase?”","explanation":"A pergunta foca na função do sinal sem avaliar leitura ou detalhes irrelevantes.","hint":"Pense no papel do ? depois da palavra.","errorFocus":"Revisar sem critério de categoria","misconceptions":{"“Qual é a cor do cartão?”":["COLOR_ONLY"],"“Quantas pessoas estão na sala?”":["ROOM_COUNT"],"“A palavra VAI tem três letras?”":["WORD_LENGTH_ONLY"]},"position":4},{"id":"v5-pt-signs-lock-05","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"CLASSIFY","contextFamily":"MIXED_SIGN_STRIP","statement":"Uma faixa mostra “A 9, seta”. Qual classificação está correta?","options":["A é algarismo, 9 é pontuação e seta é letra.","A é letra, 9 é algarismo e a seta desenhada é um ícone.","Tudo é letra porque os sinais estão na mesma faixa.","A é ícone, 9 é letra e seta é pontuação."],"correctAnswer":"A é letra, 9 é algarismo e a seta desenhada é um ícone.","explanation":"A faixa reúne três tipos de sinais, que podem ser classificados separadamente.","hint":"Classifique cada item sem usar a categoria do vizinho.","errorFocus":"Assumir que sinais próximos têm a mesma natureza","misconceptions":{"A é algarismo, 9 é pontuação e seta é letra.":["LETTER_AS_DIGIT"],"Tudo é letra porque os sinais estão na mesma faixa.":["ALL_AS_LETTERS"],"A é ícone, 9 é letra e seta é pontuação.":["MIXED_SWAP"]},"position":5},{"id":"v5-pt-signs-review-01","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"LOCATE","contextFamily":"TOY_BOX","statement":"Na etiqueta “BOLA”, qual item é uma letra?","options":["4","!","L","desenho de bola"],"correctAnswer":"L","explanation":"L integra a palavra BOLA.","hint":"Procure uma marca que forme a palavra.","errorFocus":"Confundir tipos de marcas","misconceptions":{"4":["DIGIT_AS_LETTER"],"!":["PUNCTUATION_AS_LETTER"],"desenho de bola":["IMAGE_AS_LETTER"]},"position":1},{"id":"v5-pt-signs-review-02","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"CLASSIFY","contextFamily":"DOOR_NUMBER","statement":"A porta está marcada com “2”. Qual tipo de sinal é 2?","options":["Letra.","Pontuação.","Ícone.","Algarismo."],"correctAnswer":"Algarismo.","explanation":"O 2 registra um número.","hint":"Pense em como se escreve uma quantidade ou ordem.","errorFocus":"Algarismo confundido com letra","misconceptions":{"Letra.":["LETTER_AS_DIGIT"],"Pontuação.":["PUNCT_AS_DIGIT"],"Ícone.":["ICON_AS_DIGIT"]},"position":2},{"id":"v5-pt-signs-review-03","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"CLASSIFY","contextFamily":"EXCLAMATION_NOTE","statement":"No bilhete “VIVA!”, qual marca é pontuação?","options":["!","V","I","A"],"correctAnswer":"!","explanation":"O ponto de exclamação é pontuação; as outras marcas formam a palavra.","hint":"Observe o sinal após a palavra.","errorFocus":"Pontuação confundida com letra","misconceptions":{"V":["LETTER_AS_PUNCT"],"I":["LETTER_AS_PUNCT"],"A":["LETTER_AS_PUNCT"]},"position":3},{"id":"v5-pt-signs-review-04","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"CAPITAL_INITIAL","statement":"A placa mostra “Mia” e “MIA”. O que podemos afirmar sobre M e m?","options":["Uma é letra e a outra é algarismo.","São formas maiúscula e minúscula de uma letra.","A minúscula é pontuação.","A maiúscula é uma imagem."],"correctAnswer":"São formas maiúscula e minúscula de uma letra.","explanation":"A forma visual varia, mas ambas são letras.","hint":"Observe o tipo de marca e não apenas o tamanho.","errorFocus":"Maiúscula/minúscula como tipos diferentes","misconceptions":{"Uma é letra e a outra é algarismo.":["CASE_AS_NUMBER"],"A minúscula é pontuação.":["LOWERCASE_AS_PUNCT"],"A maiúscula é uma imagem.":["UPPERCASE_AS_IMAGE"]},"position":4},{"id":"v5-pt-signs-review-05","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"RECOGNIZE","contextFamily":"MAP_ICON","statement":"Um mapa tem a letra “P” e o desenho de uma bandeira. Qual é o ícone?","options":["P.","A letra que aparece em “parque”.","O desenho da bandeira.","A palavra “P”."],"correctAnswer":"O desenho da bandeira.","explanation":"A bandeira é uma imagem usada para indicar algo; P é uma letra.","hint":"Procure a representação desenhada, não a letra.","errorFocus":"Ícone confundido com sinal alfabético","misconceptions":{"P.":["LETTER_AS_ICON"],"A letra que aparece em “parque”.":["WORD_AS_ICON"],"A palavra “P”.":["LETTER_AS_ICON"]},"position":5},{"id":"v5-pt-signs-review-06","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"COLOR_TRAP","statement":"Uma criança diz: “O número 5 virou letra porque está escrito em verde”. Qual resposta ajuda a corrigir a ideia?","options":["Sim, todo sinal verde é letra.","Só sinais pretos podem ser números.","O 5 virou pontuação por estar colorido.","A cor mudou, mas 5 continua sendo algarismo."],"correctAnswer":"A cor mudou, mas 5 continua sendo algarismo.","explanation":"A cor não muda a categoria do sinal.","hint":"Compare o que a marca representa antes e depois da cor.","errorFocus":"Cor determina categoria","misconceptions":{"Sim, todo sinal verde é letra.":["COLOR_AS_LETTER"],"Só sinais pretos podem ser números.":["BLACK_ONLY_NUMBER"],"O 5 virou pontuação por estar colorido.":["COLOR_AS_PUNCT"]},"position":6},{"id":"v5-pt-signs-review-07","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"LOCATE","contextFamily":"READ_ALOUD_SUPPORT","statement":"Um adulto lê “PATO 2!” em voz alta. A criança deve apontar uma letra, sem precisar ler sozinha. Qual escolha atende ao pedido?","options":["P","2","!","desenho de pato"],"correctAnswer":"P","explanation":"P é uma letra da palavra; a leitura mediada separa o objetivo da decodificação autônoma.","hint":"Aponte uma marca escrita dentro da palavra.","errorFocus":"Confundir classificação com leitura autônoma","misconceptions":{"2":["DIGIT_AS_LETTER"],"!":["PUNCT_AS_LETTER"],"desenho de pato":["IMAGE_AS_LETTER"]},"position":7},{"id":"v5-pt-signs-review-08","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"LOOKALIKE_FONT","statement":"Em uma fonte diferente, o algarismo 0 e a letra O parecem quase iguais. O que ajuda a distingui-los?","options":["Decidir que são sempre o mesmo sinal.","Ver como cada sinal funciona no contexto: O pode estar numa palavra e 0 numa escrita numérica.","Escolher pela cor, mesmo se ambos tiverem a mesma cor.","Evitar olhar para as palavras e números próximos."],"correctAnswer":"Ver como cada sinal funciona no contexto: O pode estar numa palavra e 0 numa escrita numérica.","explanation":"A forma parecida pede atenção ao contexto de uso, não uma regra baseada só na aparência.","hint":"Veja se a marca aparece numa palavra ou numa quantidade.","errorFocus":"Forma parecida confundida com função igual","misconceptions":{"Decidir que são sempre o mesmo sinal.":["SAME_FORM_SAME_TYPE"],"Escolher pela cor, mesmo se ambos tiverem a mesma cor.":["COLOR_ONLY"],"Evitar olhar para as palavras e números próximos.":["IGNORE_CONTEXT"]},"position":8},{"id":"v5-pt-signs-review-09","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"JUSTIFY","contextFamily":"POSTER_EXPLANATION","statement":"Um cartaz tem letras, números, pontuação e um desenho. Qual explicação mostra uma classificação cuidadosa?","options":["Tudo que está no cartaz é letra porque foi impresso.","A cor determina se cada marca é letra ou número.","Cada marca pode ser observada separadamente: letras formam palavras, algarismos registram números, pontuação organiza a escrita e imagens comunicam visualmente.","Uma imagem é uma letra sempre que fica perto de uma palavra."],"correctAnswer":"Cada marca pode ser observada separadamente: letras formam palavras, algarismos registram números, pontuação organiza a escrita e imagens comunicam visualmente.","explanation":"Diferentes sinais podem coexistir no mesmo suporte sem perder sua função própria.","hint":"Dê um exemplo de cada tipo presente.","errorFocus":"Classificar pelo suporte ou decoração","misconceptions":{"Tudo que está no cartaz é letra porque foi impresso.":["ALL_PRINTED_AS_LETTER"],"A cor determina se cada marca é letra ou número.":["COLOR_DEFINES_TYPE"],"Uma imagem é uma letra sempre que fica perto de uma palavra.":["NEIGHBOR_AS_LETTER"]},"position":9}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-portuguese-letters-signs',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'v5-portuguese-letters-signs' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'PORTUGUESE', 'SISTEMA_DE_ESCRITA', 'letras algarismos pontuacao e icones',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

